const dimensions={phone:[390,844],ipad:[1194,834],desktop:[1440,960],tv:[1920,1080]};
const names={phone:'手机',ipad:'iPad',desktop:'桌面',tv:'TV'};
const notes={phone:['PHONE','单手就能找到想看的','底部导航与横滑分组，把搜索和收藏放在拇指附近。播放时呈现独立全屏，支持回到浏览继续选台。','触控优先 · 44px 起的点击区域'],ipad:['IPAD','边看，边发现','窄侧栏释放横向空间；播放时保留右侧频道与节目单。针对横屏和分屏调整卡片数量。','横屏双栏 · 触控与键盘兼容'],desktop:['DESKTOP','把空间留给效率','常驻侧栏、即时搜索、多列频道和完整节目单。鼠标与键盘都能快速到达内容。','<kbd>/</kbd> 搜索 <kbd>Esc</kbd> 返回 <kbd>Space</kbd> 播放'],tv:['TV','从沙发上，也一目了然','为远距离观看放大字号，减少屏幕信息；用清晰的焦点框和方向键导航。返回键可逐层退出。','<kbd>↑ ↓ ← →</kbd> 导航 <kbd>Enter</kbd> 确认 <kbd>Esc</kbd> 返回']};
const q=new URLSearchParams(location.search);let style=['nocturne','paper','signal'].includes(q.get('style'))?q.get('style'):'nocturne';let device=dimensions[q.get('device')]?q.get('device'):(innerWidth<700?'phone':'desktop');let page=['home','channels','guide','favorites','sources','remote','settings','player'].includes(q.get('page'))?q.get('page'):'home';let overview=q.get('overview')==='1';let state=window.XP_STATES[q.get('state')]?q.get('state'):'normal';document.querySelector('#state-select').innerHTML=Object.entries(window.XP_STATES).map(([id,s])=>`<option value="${id}">${s.label}</option>`).join('');
const stage=document.querySelector('#preview-stage');let frame,wrap;
function url(d=device){return `preview.html?style=${style}&device=${d}&page=${page}&state=${state}`}
function syncURL(){const u=new URL(location);u.searchParams.set('style',style);u.searchParams.set('device',device);u.searchParams.set('page',page);u.searchParams.set('state',state);overview?u.searchParams.set('overview','1'):u.searchParams.delete('overview');history.replaceState(null,'',u)}
function makeFrame(d){const w=document.createElement('div');w.className='frame-wrap '+d;const f=document.createElement('iframe');f.title=`${names[d]}端 ${style} 设计预览`;f.src=url(d);f.width=dimensions[d][0];f.height=dimensions[d][1];w.append(f);return w}
function scaleFrame(w,d,maxW){const f=w.querySelector('iframe'),[width,height]=dimensions[d],border=d==='phone'?14:d==='ipad'?18:d==='tv'?12:2;const scale=Math.min(1,(maxW-border)/width);f.style.transform=`scale(${scale})`;f.style.width=width+'px';f.style.height=height+'px';w.style.width=width*scale+border+'px';w.style.height=height*scale+border+'px';return scale}
function fit(){if(overview){stage.querySelectorAll('.overview-item').forEach(el=>{const d=el.dataset.device;scaleFrame(el.querySelector('.frame-wrap'),d,Math.min(el.clientWidth-30,d==='phone'?230:900))})}else{const pad=innerWidth<700?26:innerWidth>=1700?106:66;const scale=scaleFrame(wrap,device,stage.clientWidth-pad);document.querySelector('#scale-label').textContent=Math.round(scale*100)+'% · 自适应缩放'}}
function render(){if(style!=='nocturne')state='normal';document.querySelector('#state-select').disabled=style!=='nocturne';document.querySelector('#state-select').title=style==='nocturne'?'A 主方案的完整边界状态':'B/C 保留原有方案，不扩充边界状态';document.querySelectorAll('[data-style]').forEach(b=>{b.classList.toggle('selected',b.dataset.style===style);b.setAttribute('aria-pressed',b.dataset.style===style)});document.querySelectorAll('.devices [data-device]').forEach(b=>{b.classList.toggle('selected',b.dataset.device===device);b.setAttribute('aria-pressed',b.dataset.device===device)});stage.classList.toggle('overview',overview);stage.replaceChildren();if(overview){for(const d of ['phone','ipad','desktop','tv']){const item=document.createElement('button');item.className='overview-item';item.dataset.device=d;item.innerHTML=`<div class="overview-label"><b>${names[d]}</b><span>${dimensions[d].join(' × ')} ↗</span></div>`;item.append(makeFrame(d));item.addEventListener('click',()=>{device=d;overview=false;render()});stage.append(item)}}else{wrap=makeFrame(device);stage.append(wrap);frame=wrap.querySelector('iframe');frame.id='app-frame'}document.querySelector('#viewport-label').textContent=(overview?'四端总览':names[device]+' · '+dimensions[device].join(' × '));document.querySelector('#overview-button').classList.toggle('active',overview);document.querySelector('#overview-button').textContent=overview?'返回单端':'四端总览';document.querySelector('#page-select').value=page;document.querySelector('#state-select').value=state;const n=notes[device];document.querySelector('#note-device').textContent=n[0];document.querySelector('#note-title').textContent=n[1];document.querySelector('#note-body').textContent=n[2];document.querySelector('#note-shortcut').innerHTML=n[3];syncURL();requestAnimationFrame(fit)}
document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{style=b.dataset.style;render()});document.querySelectorAll('.devices [data-device]').forEach(b=>b.onclick=()=>{device=b.dataset.device;overview=false;render()});document.querySelector('#page-select').onchange=e=>{page=e.target.value;state='normal';render()};document.querySelector('#state-select').onchange=e=>{state=e.target.value;page=window.XP_STATES[state].page;render()};document.querySelector('#overview-button').onclick=()=>{overview=!overview;render()};document.querySelector('#standalone-button').onclick=()=>window.open(url(),'_blank','noopener');document.querySelector('#principles-button').onclick=()=>document.querySelector('#principles').scrollIntoView({behavior:'smooth'});
document.querySelector('#copy-button').onclick=async()=>{let message='已复制当前风格、设备和页面的链接';try{await navigator.clipboard.writeText(location.href)}catch{message='请复制浏览器地址栏中的当前链接'}const t=document.querySelector('#studio-toast');t.textContent=message;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),2500)};
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;if(e.data?.type==='xplayer-state'&&!overview){state=e.data.state;page=e.data.page;document.querySelector('#state-select').value=state;document.querySelector('#page-select').value=page;syncURL();return}if(e.data?.type==='xplayer-style'&&!overview){style=e.data.style;render();return}if(e.data?.type==='xplayer-page'&&!overview){page=e.data.page;document.querySelector('#page-select').value=page;syncURL()}});new ResizeObserver(fit).observe(stage);render();
